// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function _test(uint256 depositAmount, uint256 newRate) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(newRate != 100);
        vm.assume(address(this).balance >= depositAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        try c.setRewardRate(newRate) {} catch { return; }
        uint256 claimed;
        try c.claim() returns (uint256 __r) { claimed = __r; } catch { return; }
        uint256 rewardAfter;
        try c.reward(address(this)) returns (uint256 __r) { rewardAfter = __r; } catch { return; }
        assertTrue(rewardAfter == depositAmount * 100);
    }

    function testFuzz_test(uint256 depositAmount, uint256 newRate) public {
        _test(depositAmount, newRate);
    }

    receive() external payable {}
}
